-- Generated by apps/vakt/supabase/build.mjs. Vakt's tables and functions only (all named vakt_*).
-- Paste into Supabase > SQL Editor > New query, then Run. Safe to run again; it never touches the other apps.

-- ===== 0001_vakt_init.sql =====
-- Vakt: shifts, supplements (tillegg) and settings for one person's pay.
--
-- Vakt shares a Supabase project with Home Memory, Post and Ledger but nothing else. Every object it creates is named
-- vakt_*, it never alters another app's tables, and it has no foreign keys to auth.users: the rows are tied to the
-- user id, so deleting a Home Memory account can neither delete Vakt data nor be blocked by it. Safe to run again.

-- ---------------------------------------------------------------------------------------------------------------
-- Settings: one row per person. Hourly wages, goal, tax and shift templates (see src/lib/types.ts Settings).
create table if not exists public.vakt_profiles (
  owner_id uuid primary key default auth.uid(),
  settings jsonb not null default '{}'::jsonb check (jsonb_typeof(settings) = 'object' and pg_column_size(settings) < 16384),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------------------------------------------
-- Supplements (tillegg). A window whose end is at or before its start runs past midnight; equal means all day.
create table if not exists public.vakt_supplements (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid(),
  name text not null check (char_length(btrim(name)) between 1 and 60),
  color text not null default '#8b5cf6' check (color ~ '^#[0-9a-fA-F]{6}$'),
  amount_type text not null check (amount_type in ('kr_per_hour', 'percent', 'kr_per_shift')),
  amount numeric(10, 2) not null check (amount >= 0 and amount <= 100000),
  min_per_hour numeric(10, 2) check (min_per_hour is null or (min_per_hour >= 0 and min_per_hour <= 10000)),
  days text[] not null check (cardinality(days) between 1 and 9
    and days <@ array['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun', 'holiday', 'holiday_eve']),
  start_time text not null check (start_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  end_time text not null check (end_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  active boolean not null default true,
  sort integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists vakt_supplements_owner on public.vakt_supplements (owner_id);

-- ---------------------------------------------------------------------------------------------------------------
-- Shifts. An end at or before the start means the shift ends the next day.
create table if not exists public.vakt_shifts (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid(),
  date date not null check (date between '2000-01-01' and '2100-12-31'),
  start_time text not null check (start_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  end_time text not null check (end_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  break_minutes integer not null default 0 check (break_minutes between 0 and 600),
  overtime_percent integer not null default 0 check (overtime_percent between 0 and 300),
  note text not null default '' check (char_length(note) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists vakt_shifts_owner_date on public.vakt_shifts (owner_id, date);

-- ---------------------------------------------------------------------------------------------------------------
create or replace function public.vakt_touch() returns trigger language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['vakt_profiles', 'vakt_supplements', 'vakt_shifts'] loop
    execute format('drop trigger if exists %I on public.%I', t || '_touch', t);
    execute format('create trigger %I before update on public.%I for each row execute function public.vakt_touch()', t || '_touch', t);
  end loop;
end $$;

-- ---------------------------------------------------------------------------------------------------------------
-- Row level security: a person sees and changes only their own rows; signed-out visitors see nothing.
alter table public.vakt_profiles enable row level security;
alter table public.vakt_supplements enable row level security;
alter table public.vakt_shifts enable row level security;

revoke all on public.vakt_profiles, public.vakt_supplements, public.vakt_shifts from anon;
grant select, insert, update, delete on public.vakt_profiles, public.vakt_supplements, public.vakt_shifts to authenticated;

do $$
declare t text;
begin
  foreach t in array array['vakt_profiles', 'vakt_supplements', 'vakt_shifts'] loop
    execute format('drop policy if exists %I on public.%I', t || '_own', t);
    execute format('create policy %I on public.%I for all to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid())', t || '_own', t);
  end loop;
end $$;

-- ===== 0002_vakt_employers.sql =====
-- Employers: she can work for more than one employer or department, each with its own wage, shift types and
-- supplements. Shifts and supplements say which employer they belong to. Safe to run again.

create table if not exists public.vakt_employers (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid(),
  name text not null check (char_length(btrim(name)) between 1 and 60),
  color text not null default '#7c3aed' check (color ~ '^#[0-9a-fA-F]{6}$'),
  -- [{ "from": "2026-01-01", "hourly": 285 }] and [{ "id", "name", "start_time", "end_time", "break_minutes" }]
  wages jsonb not null default '[]'::jsonb check (jsonb_typeof(wages) = 'array' and pg_column_size(wages) < 8192),
  templates jsonb not null default '[]'::jsonb check (jsonb_typeof(templates) = 'array' and pg_column_size(templates) < 8192),
  sort integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, owner_id)
);
create index if not exists vakt_employers_owner on public.vakt_employers (owner_id);

alter table public.vakt_shifts add column if not exists employer_id uuid;
alter table public.vakt_supplements add column if not exists employer_id uuid;

-- An employer can only be used by its own owner. Shifts keep their employer (delete or move the shifts first);
-- supplements go with it.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'vakt_shifts_employer') then
    alter table public.vakt_shifts add constraint vakt_shifts_employer
      foreign key (employer_id, owner_id) references public.vakt_employers (id, owner_id) on delete restrict;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'vakt_supplements_employer') then
    alter table public.vakt_supplements add constraint vakt_supplements_employer
      foreign key (employer_id, owner_id) references public.vakt_employers (id, owner_id) on delete cascade;
  end if;
end $$;
create index if not exists vakt_shifts_employer_idx on public.vakt_shifts (employer_id);
create index if not exists vakt_supplements_employer_idx on public.vakt_supplements (employer_id);

-- Anyone who used Vakt before this: one employer from the wage and shift types in their settings, and every
-- existing shift and supplement moved to it.
insert into public.vakt_employers (owner_id, name, wages, templates)
select o.owner_id, 'Jobben min',
       coalesce(p.settings->'wages', '[]'::jsonb), coalesce(p.settings->'templates', '[]'::jsonb)
from (select owner_id from public.vakt_profiles union select owner_id from public.vakt_shifts union select owner_id from public.vakt_supplements) o
left join public.vakt_profiles p on p.owner_id = o.owner_id
where not exists (select 1 from public.vakt_employers e where e.owner_id = o.owner_id);

update public.vakt_shifts s set employer_id = (select e.id from public.vakt_employers e where e.owner_id = s.owner_id order by e.sort, e.created_at limit 1)
where s.employer_id is null;
update public.vakt_supplements s set employer_id = (select e.id from public.vakt_employers e where e.owner_id = s.owner_id order by e.sort, e.created_at limit 1)
where s.employer_id is null;

drop trigger if exists vakt_employers_touch on public.vakt_employers;
create trigger vakt_employers_touch before update on public.vakt_employers for each row execute function public.vakt_touch();

alter table public.vakt_employers enable row level security;
revoke all on public.vakt_employers from anon;
grant select, insert, update, delete on public.vakt_employers to authenticated;
drop policy if exists vakt_employers_own on public.vakt_employers;
create policy vakt_employers_own on public.vakt_employers for all to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid());

-- ===== 0003_vakt_pay_and_reminders.sql =====
-- Version 3: when pay lands in the account (pay day, and supplements paid the month after), sick shifts, days off,
-- pay slips to check the numbers against, and reminders on the phone (Web Push). Additive only; safe to run again.

-- Pay day and what is paid a month late. Most health-care employers pay the hourly wage for the month worked and
-- supplements and overtime the month after ('supplements'); some pay everything the month after ('all').
alter table public.vakt_employers add column if not exists pay_day integer not null default 12;
alter table public.vakt_employers add column if not exists pay_delay text not null default 'supplements';
alter table public.vakt_employers drop constraint if exists vakt_employers_pay_day;
alter table public.vakt_employers add constraint vakt_employers_pay_day check (pay_day between 1 and 31);
alter table public.vakt_employers drop constraint if exists vakt_employers_pay_delay;
alter table public.vakt_employers add constraint vakt_employers_pay_delay check (pay_delay in ('none', 'supplements', 'all'));

-- A shift she was sick for is still listed, paid at the sick-pay share from Oppsett.
alter table public.vakt_shifts add column if not exists status text not null default 'worked';
alter table public.vakt_shifts drop constraint if exists vakt_shifts_status;
alter table public.vakt_shifts add constraint vakt_shifts_status check (status in ('worked', 'sick'));

-- Days off: holiday, a day off, time off in lieu. They pay nothing; they show in the calendar.
create table if not exists public.vakt_days_off (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid(),
  date date not null check (date between '2000-01-01' and '2100-12-31'),
  kind text not null check (kind in ('ferie', 'fri', 'avspasering')),
  note text not null default '' check (char_length(note) <= 200),
  created_at timestamptz not null default now(),
  unique (owner_id, date)
);

-- What the pay slip said for a month, to compare with what Vakt worked out for that pay day.
create table if not exists public.vakt_payslips (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid(),
  month text not null check (month ~ '^\d{4}-(0[1-9]|1[0-2])$'),
  gross numeric(12, 2) not null check (gross >= 0 and gross < 10000000),
  net numeric(12, 2) check (net is null or (net >= 0 and net < 10000000)),
  note text not null default '' check (char_length(note) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (owner_id, month)
);
drop trigger if exists vakt_payslips_touch on public.vakt_payslips;
create trigger vakt_payslips_touch before update on public.vakt_payslips for each row execute function public.vakt_touch();

-- A browser's Web Push subscription. The keys only let a sender encrypt to that browser; they are not a login.
create table if not exists public.vakt_push_devices (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null default auth.uid(),
  endpoint text not null check (endpoint ~ '^https://' and char_length(endpoint) <= 1000),
  p256dh text not null check (char_length(p256dh) between 20 and 200),
  auth text not null check (char_length(auth) between 8 and 100),
  created_at timestamptz not null default now(),
  unique (owner_id, endpoint)
);

do $$
declare t text;
begin
  foreach t in array array['vakt_days_off', 'vakt_payslips', 'vakt_push_devices'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
    execute format('grant select, insert, update, delete on public.%I to authenticated', t);
    execute format('drop policy if exists %I on public.%I', t || '_own', t);
    execute format('create policy %I on public.%I for all to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid())', t || '_own', t);
  end loop;
end $$;

-- What the vakt-notify function has already sent, so repeated runs never notify twice, and when it last ran.
-- Server only: row level security with no policies, so only the function (service role) reads or writes them.
create table if not exists public.vakt_push_sent (
  owner_id uuid not null,
  key text not null check (char_length(key) <= 200),
  sent_at timestamptz not null default now(),
  primary key (owner_id, key)
);
alter table public.vakt_push_sent enable row level security;
revoke all on public.vakt_push_sent from anon, authenticated;

create table if not exists public.vakt_notify_status (
  id boolean primary key default true check (id),
  last_run timestamptz
);
alter table public.vakt_notify_status enable row level security;
revoke all on public.vakt_notify_status from anon, authenticated;

notify pgrst, 'reload schema';
